# Test bool strict
for v in ["1","0","true","false","True","False","TRUE","FALSE","00","01"," 1","1 ","0x1",""]:
    rc,out,err=test("bool",v,False)
    print(f"bool strict {repr(v)} => {rc} {repr(out[:100])} {repr(err[:200])}")
print("---lenient bool---")
for v in ["1","0","true","false","True","yes",""]:
    rc,out,err=test("bool",v,True)
    print(f"bool lenient {repr(v)} => {rc} {repr(out[:100])} {repr(err[:200])}")
PY
"}

