use std::env;
use std::fs;
use std::process;

fn prog_name() -> String {
    let arg0 = env::args().next().unwrap_or_else(|| "executable".to_string());
    // basename
    let p = arg0.rsplit('/').next().unwrap_or(&arg0);
    let p = p.rsplit('\\').next().unwrap_or(p);
    p.to_string()
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let prog = prog_name();
    let code = run(&args, &prog);
    process::exit(code);
}

fn run(args: &[String], prog: &str) -> i32 {
    // args[0] is prog
    let rest = if args.len() > 1 { &args[1..] } else { &[][..] };
    handle_top(rest, prog)
}

// ============ HELP TEXTS ============
fn top_help(prog: &str) -> String {
    format!("ethabi-cli 18.0.0\nEthereum ABI coder\n\nUSAGE:\n    {} <SUBCOMMAND>\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nSUBCOMMANDS:\n    decode    Decode ABI call result\n    encode    Encode ABI call\n    help      Prints this message or the help of the given subcommand(s)\n", prog)
