    let arg0 = env::args().next().unwrap_or_else(|| "executable".to_string());
    // basename
    let p = arg0.rsplit('/').next().unwrap_or(&arg0);
    let p = p.rsplit('\\').next().unwrap_or(p);
    p.to_string()
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let prog = prog_name();
    let code = run(&args, &prog);
    process::exit(code);
}

fn run(args: &[String], prog: &str) -> i32 {
    // args[0] is prog
    let rest = if args.len() > 1 { &args[1..] } else { &[][..] };
    handle_top(rest, prog)
}

