// ============ CLI helpers ============
fn print_stdout(s: &str) { print!("{}", s); use std::io::Write; std::io::stdout().flush().ok(); }
fn print_stderr(s: &str) { eprint!("{}", s); use std::io::Write; std::io::stderr().flush().ok(); }

fn jaro_winkler(a: &str, b: &str) -> f64 {
    strsim::jaro_winkler(a, b)
}

fn suggest_subcommand(input: &str, candidates: &[&str]) -> Option<String> {
    let mut best: Option<(f64, &str)> = None;
    for c in candidates {
        let conf = jaro_winkler(input, c);
        if conf > 0.8 {
            if best.map_or(true, |(b,_)| conf > b) {
                best = Some((conf, c));
            }
        }
    }
    best.map(|(_, s)| s.to_string())
}

fn suggest_flag(input: &str, candidates: &[&str]) -> Option<String> {
    // input like "--hel", candidates like ["--help","--version"]
    let mut best: Option<(f64, &str)> = None;
    for c in candidates {
        let conf = jaro_winkler(input, c);
        if conf > 0.8 {
            if best.map_or(true, |(b,_)| conf > b) {
                best = Some((conf, c));
            }
        }
    }
    best.map(|(_, s)| s.to_string())
}

fn colored_flag(flag: &str) -> String {
    // flag like "--help" -> "\x1b[32m--\x1b[0m\x1b[32mhelp\x1b[0m"
    // split into "--" + rest?
    if flag.starts_with("--") {
        format!("\x1b[32m--\x1b[0m\x1b[32m{}\x1b[0m", &flag[2..])
    } else {
        flag.to_string()
    }
}
