    ];
    let rot_offsets: [[u32; 5]; 5] = [
        [0, 36, 3, 41, 18],
        [1, 44, 10, 45, 2],
        [62, 6, 43, 15, 61],
        [28, 55, 25, 21, 56],
        [27, 20, 39, 8, 14],
    ];
    // Actually use standard rotation table indexed by [x][y]
    // keccak rotation offsets r[x][y]
    let r: [[u32; 5]; 5] = [
        [0, 36, 3, 41, 18],
        [1, 44, 10, 45, 2],
        [62, 6, 43, 15, 61],
        [28, 55, 25, 21, 56],
        [27, 20, 39, 8, 14],
    ];
    for &rc in round_constants.iter() {
        // Theta
        let mut c = [0u64; 5];
        for x in 0..5 {
            c[x] = state[x] ^ state[x+5] ^ state[x+10] ^ state[x+15] ^ state[x+20];
        }
        let mut d = [0u64; 5];
        for x in 0..5 {
            d[x] = c[(x+4)%5].rotate_left(1) ^ c[(x+1)%5];
        }
        for x in 0..5 {
            for y in 0..5 {
                state[x + 5*y] ^= d[x];
            }
        }
        // Rho Pi
        let mut b = [0u64; 25];
        for x in 0..5 {
            for y in 0..5 {
                let idx = x + 5*y;
                // new position: y, (2*x+3*y)%5
                let nx = y;
                let ny = (2*x + 3*y) % 5;
                let nidx = nx + 5*ny;
                b[nidx] = state[idx].rotate_left(r[x][y]);
            }
        }
        // Chi
        for x in 0..5 {
            for y in 0..5 {
                let idx = x + 5*y;
                state[idx] = b[idx] ^ ((!b[(x+1)%5 + 5*y]) & b[(x+2)%5 + 5*y]);
            }
        }
        // Iota
        state[0] ^= rc;
    }
}

fn keccak256(data: &[u8]) -> [u8; 32] {
    let mut state = [0u64; 25];
    let block_size = 136; // 1088 bits for keccak-256
    let mut offset = 0;
    while data.len() - offset >= block_size {
        for i in 0..(block_size/8) {
            let mut bytes = [0u8; 8];
            bytes.copy_from_slice(&data[offset + i*8 .. offset + (i+1)*8]);
            state[i] ^= u64::from_le_bytes(bytes);
        }
        keccak_f1600(&mut state);
        offset += block_size;
    }
    // padding: 0x01 ... 0x80
    let mut last = vec![0u8; block_size];
    let rem = data.len() - offset;
    last[..rem].copy_from_slice(&data[offset..]);
    last[rem] = 0x01;
    last[block_size-1] |= 0x80;
    for i in 0..(block_size/8) {
        let mut bytes = [0u8; 8];
        bytes.copy_from_slice(&last[i*8 .. (i+1)*8]);
        state[i] ^= u64::from_le_bytes(bytes);
    }
    keccak_f1600(&mut state);
    let mut out = [0u8; 32];
    for i in 0..4 {
        out[i*8..(i+1)*8].copy_from_slice(&state[i].to_le_bytes());
    }
    out
}
