        match parse_type(kind) {
            Ok(t) => Ok(t),
            Err(TypeParseError::InvalidName(s)) => Err(format!("InvalidName(\"{}\")", s)),
            Err(TypeParseError::IntegerParse(s)) => Err(format!("ParseInt({})", s)),
        }
    }
