                    Ok(Token::FixedBytes(b))
                },
                Err(e) => {
                    let msg = e.to_string();
                    return Err(format!("Hex parsing error: {}\n\nCaused by:\n    {}", msg, msg));
                }
            }
        },
        ParamType::Uint(_) => {
            match hex::decode(value) {
                Ok(b) => {
                    if b.len() != 32 { return Err("Invalid data".to_string()); }
                    let mut a = [0u8;32];
                    a.copy_from_slice(&b);
                    Ok(Token::Uint(a))
                },
                Err(e) => {
                    let msg = e.to_string();
                    return Err(format!("Hex parsing error: {}\n\nCaused by:\n    {}", msg, msg));
                }
            }
        },
        ParamType::Int(_) => {
            match hex::decode(value) {
                Ok(b) => {
                    if b.len() != 32 { return Err("Invalid data".to_string()); }
                    let mut a = [0u8;32];
                    a.copy_from_slice(&b);
                    Ok(Token::Int(a))
                },
                Err(e) => {
                    let msg = e.to_string();
                    return Err(format!("Hex parsing error: {}\n\nCaused by:\n    {}", msg, msg));
                }
            }
        },
        ParamType::Bool => {
            match value {
                "1" | "true" => Ok(Token::Bool(true)),
                "0" | "false" => Ok(Token::Bool(false)),
                _ => Err("Invalid data".to_string()),
            }
        },
        ParamType::String => {
            Ok(Token::String(value.to_string()))
        },
        ParamType::Array(inner) => {
            // value must be [..]
            if !value.starts_with('[') || !value.ends_with(']') {
                return Err("Invalid data".to_string());
            }
            let inner_str = &value[1..value.len()-1];
            if inner_str.is_empty() {
                return Ok(Token::Array(vec![]));
