                let t = tokenize_strict(&types[i], p)?;
                toks.push(t);
            }
            Ok(Token::Tuple(toks))
        },
    }
}

fn tokenize_lenient(ty: &ParamType, value: &str) -> Result<Token, String> {
    match ty {
        ParamType::Address | ParamType::Bytes | ParamType::FixedBytes(_) | ParamType::Bool | ParamType::String => {
            // Same as strict for these (address/bytes/bool/string same)
            return tokenize_strict(ty, value);
        },
        ParamType::Uint(_) => {
            // If len==64 and valid hex, treat as hex (strict)
            if value.len() == 64 {
                if let Ok(b) = hex::decode(value) {
                    if b.len() == 32 {
                        let mut a = [0u8;32];
                        a.copy_from_slice(&b);
                        return Ok(Token::Uint(a));
                    }
                }
            }
            // Else decimal
            match parse_dec_to_u256(value) {
                Ok(b) => Ok(Token::Uint(b)),
                Err(e) => Err(format!("Uint parse error: {}", e)),
            }
        },
        ParamType::Int(_) => {
            if value.len() == 64 {
                if let Ok(b) = hex::decode(value) {
                    if b.len() == 32 {
                        let mut a = [0u8;32];
                        a.copy_from_slice(&b);
                        return Ok(Token::Int(a));
                    }
                }
            }
