                Err(e) => {
                    // For int, error is also "Uint parse error"? Observed int lenient with "+1" gives "Uint parse error: InvalidCharacter", not "Int parse error".
                    // So use same prefix.
                    Err(format!("Uint parse error: {}", e))
                },
            }
        },
        ParamType::Array(inner) => {
            if !value.starts_with('[') || !value.ends_with(']') {
                return Err("Invalid data".to_string());
            }
            let inner_str = &value[1..value.len()-1];
            if inner_str.is_empty() {
                return Ok(Token::Array(vec![]));
            }
            let parts = split_top_level(inner_str);
            let mut toks = Vec::new();
            for p in parts {
