                } else {
                    return Err("Invalid data".to_string());
                }
            }
            let parts = split_top_level(inner_str);
            if parts.len() != *n {
                return Err("Invalid data".to_string());
            }
            let mut toks = Vec::new();
            for p in parts {
                let t = tokenize_lenient(inner, &p)?;
                toks.push(t);
            }
            Ok(Token::FixedArray(toks))
        },
        ParamType::Tuple(types) => {
            if !value.starts_with('(') || !value.ends_with(')') {
                return Err("Invalid data".to_string());
            }
            let inner_str = &value[1..value.len()-1];
            if inner_str.is_empty() {
                return Ok(Token::Tuple(vec![]));
            }
            let parts = split_top_level(inner_str);
            if parts.len() > types.len() {
                return Err("Invalid data".to_string());
            }
            let mut toks = Vec::new();
            for (i, p) in parts.iter().enumerate() {
                let t = tokenize_lenient(&types[i], p)?;
                toks.push(t);
            }
            Ok(Token::Tuple(toks))
        },
    }
}
