// ============ ABI file handling (simplified) ============
use serde::Deserialize;
use serde::de::{self, Deserializer, MapAccess, Visitor};
use std::fmt;

#[derive(Debug)]
struct AbiFunction {
    name: String,
    inputs: Vec<(String, ParamType)>,
    outputs: Vec<(String, ParamType)>,
    // inputs as (name, type), outputs similarly
}

#[derive(Debug)]
struct AbiEvent {
    name: String,
    inputs: Vec<(String, ParamType, bool)>, // name, type, indexed
    anonymous: bool,
}

// Raw structs for serde (with correct required fields)
#[derive(Debug, Deserialize)]
#[serde(tag = "type")]
enum AbiEntryRaw {
    #[serde(rename = "constructor")]
    Constructor { inputs: Vec<AbiParamRaw> },
    #[serde(rename = "function")]
    Function { name: String, inputs: Vec<AbiParamRaw>, outputs: Vec<AbiParamRaw> },
    #[serde(rename = "event")]
    Event { name: String, inputs: Vec<AbiEventParamRaw>, anonymous: bool },
    #[serde(rename = "error")]
    Error { name: String, inputs: Vec<AbiParamRaw> },
    #[serde(rename = "fallback")]
    Fallback {},
    #[serde(rename = "receive")]
    Receive {},
}

#[derive(Debug, Deserialize)]
struct AbiParamRaw {
