    indexed: Option<bool>,
}

fn load_abi(path: &str) -> Result<(Vec<AbiFunction>, Vec<AbiEvent>), String> {
    // Read file
    let content = match std::fs::read_to_string(path) {
        Ok(c) => c,
        Err(e) => {
            let code = e.raw_os_error().unwrap_or(2);
            let msg = if code == 2 {
                "No such file or directory (os error 2)".to_string()
            } else if code == 21 {
                // Is a directory: need Serialization error with Caused by
                return Err(format!("Serialization error: Is a directory (os error 21)\n\nCaused by:\n    Is a directory (os error 21)"));
            } else {
                format!("{} (os error {})", e.to_string(), code)
            };
            // For file not found, error is "No such file..." without Serialization prefix? Observed: "Error: No such file or directory (os error 2)\n" (no Caused by, no Serialization prefix)
            // For Is a directory, error is "Serialization error: ..." with Caused by.
            // So handle separately.
            if code == 2 {
                return Err(msg);
            } else {
                return Err(format!("Serialization error: {}\n\nCaused by:\n    {}", msg, msg));
            }
        }
    };
    // Parse JSON
    let entries: Vec<AbiEntryRaw> = match serde_json::from_str(&content) {
        Ok(v) => v,
        Err(e) => {
            // serde_json error already has "at line X column Y"? Actually e.to_string() includes "at line X column Y".
            // Need to format as "Serialization error: {e}\n\nCaused by:\n    {e}"
            let msg = e.to_string();
            return Err(format!("Serialization error: {}\n\nCaused by:\n    {}", msg, msg));
