fn canonical_type(ty: &ParamType) -> String {
    match ty {
        ParamType::Address => "address".to_string(),
        ParamType::Bool => "bool".to_string(),
        ParamType::String => "string".to_string(),
        ParamType::Bytes => "bytes".to_string(),
        ParamType::Int(n) => {
            if *n == 256 { "int256".to_string() } else { format!("int{}", n) }
        },
        ParamType::Uint(n) => {
            if *n == 256 { "uint256".to_string() } else { format!("uint{}", n) }
        },
        ParamType::FixedBytes(n) => format!("bytes{}", n),
        ParamType::Array(t) => format!("{}[]", canonical_type(t)),
        ParamType::FixedArray(t, n) => format!("{}[{}]", canonical_type(t), n),
        ParamType::Tuple(v) => {
            if v.is_empty() { "()".to_string() }
