                    return 0;
                }
            }
        }
    }
    // Parse: <abi-path> <function> <data> (all positionals, no options), with -- separator support
    let mut positionals: Vec<String> = Vec::new();
    let mut seen_dashdash = false;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if seen_dashdash {
            positionals.push(a.clone());
            if positionals.len() > 3 {
                print_stderr(&format!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {} decode function <abi-path> <function-name-or-signature> <data>\n\nFor more information try --help\n", a, prog));
                return 1;
            }
            i += 1;
            continue;
        }
        if a == "--" {
            seen_dashdash = true;
            i += 1;
            continue;
        }
        if a.starts_with("--") {
            let cands = ["--help", "--version"];
            let mut best: Option<(f64, &str)> = None;
            for c in &cands {
                let conf = strsim::jaro_winkler(a, c);
                if conf > 0.8 {
                    if best.map_or(true, |(b,_)| conf > b) { best = Some((conf, *c)); }
                }
            }
            if let Some((_, sug)) = best {
                let col = format!("\x1b[32m--\x1b[0m\x1b[32m{}\x1b[0m", &sug[2..]);
                print_stderr(&format!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\tDid you mean {}?\n\nUSAGE:\n    {} decode function --help\n\nFor more information try --help\n", a, col, prog));
                return 1;
            } else {
                print_stderr(&format!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {} decode function <abi-path> <function-name-or-signature> <data>\n\nFor more information try --help\n", a, prog));
                return 1;
            }
        }
        if a.starts_with('-') {
            print_stderr(&format!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {} decode function <abi-path> <function-name-or-signature> <data>\n\nFor more information try --help\n", a, prog));
            return 1;
        }
        positionals.push(a.clone());
        if positionals.len() > 3 {
            print_stderr(&format!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {} decode function <abi-path> <function-name-or-signature> <data>\n\nFor more information try --help\n", a, prog));
            return 1;
        }
        i += 1;
    }
    if positionals.len() < 3 {
        if positionals.is_empty() {
            print_stderr(&format!("error: The following required arguments were not provided:\n    <abi-path>\n    <function-name-or-signature>\n    <data>\n\nUSAGE:\n    {} decode function <abi-path> <function-name-or-signature> <data>\n\nFor more information try --help\n", prog));
