            print_stderr(&format!("error: The following required arguments were not provided:\n    <data>\n\nUSAGE:\n    {} decode function <abi-path> <function-name-or-signature> <data>\n\nFor more information try --help\n", prog));
            return 1;
        }
    }
    let abi_path = &positionals[0];
    let func_name = &positionals[1];
    let data_str = &positionals[2];
    let (funcs, _) = match load_abi(abi_path) {
        Ok(v) => v,
        Err(e) => {
            print_stderr(&format!("Error: {}\n", e));
            return 1;
        }
    };
    let func = match find_function(&funcs, func_name) {
        Ok(f) => f,
        Err(e) => {
            print_stderr(&format!("Error: {}\n", e));
            return 1;
        }
    };
    // Decode outputs (not inputs) from data
    let out_types: Vec<ParamType> = func.outputs.iter().map(|(_, t)| t.clone()).collect();
    let out_names: Vec<String> = func.outputs.iter().map(|(n, _)| n.clone()).collect();
    let data_bytes = match hex::decode(data_str) {
        Ok(b) => b,
        Err(e) => {
            print_stderr(&format!("Error: {}\n", e.to_string()));
            return 1;
        }
    };
    let tokens = match decode_tokens(&out_types, &data_bytes) {
        Ok(t) => t,
        Err(e) => {
            if e == "empty" {
                print_stderr("Error: Invalid name: please ensure the contract and method you're calling exist! failed to decode empty bytes. if you're using jsonrpc this is likely due to jsonrpc returning `0x` in case contract or method don't exist\n");
                return 1;
            } else {
                print_stderr("Error: Invalid data\n");
                return 1;
            }
        }
    };
    if out_types.is_empty() {
        print_stdout("");
        return 0;
    }
    let mut out = String::new();
    for ((ty, tok), name) in out_types.iter().zip(tokens.iter()).zip(out_names.iter()) {
        // For function outputs, format as "type value"? Or "name value"? Observed: decode function for eip20 transfer (outputs bool) gives "bool true" (type, not name)? For Operations release (outputs uint32 etc with names o_forkBlock etc), what output? Let's test: decode release outputs should be "uint32 1\nuint8 2..." (types, not names)? Earlier decode release gave "uint32 1\nuint8 2\nuint24 3\nbool true" (types). Good, so use types, not names.
        // For test.abi bar(string) outputs uint256 with name "b"? Decode gave "uint256 5" (type). Good.
        out.push_str(&format_token(ty, tok));
        out.push('\n');
    }
    print_stdout(&out);
    return 0;
}

