fn decode_static_topic(ty: &ParamType, topic: &[u8;32]) -> Result<Token, String> {
    // Decode 32-byte topic as static type (for indexed)
    // For bool: check first 31 zero, last byte 1=>true else false
    // For address: last 20 bytes
    // For uint/int: full 32
    // For FixedBytes(n): first n bytes
    // For others (dynamic): fail?
    match ty {
        ParamType::Address => {
            let mut a = [0u8;20];
            a.copy_from_slice(&topic[12..32]);
            Ok(Token::Address(a))
        },
        ParamType::Bool => {
            for i in 0..31 {
                if topic[i] != 0 { return Err("Invalid data".to_string()); }
            }
            Ok(Token::Bool(topic[31] == 1))
        },
        ParamType::Uint(_) => {
            let mut b = [0u8;32];
            b.copy_from_slice(topic);
            Ok(Token::Uint(b))
        },
        ParamType::Int(_) => {
            let mut b = [0u8;32];
            b.copy_from_slice(topic);
            Ok(Token::Int(b))
        },
        ParamType::FixedBytes(n) => {
            if *n == 0 {
                return Ok(Token::FixedBytes(vec![]));
            }
            if *n > 32 { return Err("Invalid data".to_string()); }
            Ok(Token::FixedBytes(topic[..*n].to_vec()))
        },
        ParamType::String | ParamType::Bytes | ParamType::Array(_) => {
            // Dynamic indexed: topic is hash, cannot decode. For now, fail?
            // What does ethabi do for dynamic indexed? It probably decodes topic as FixedBytes(32) hash? Let's check: for Changed (address[] indexed), topic would be hash, output would be hash as bytes? Or as address[]?
            // Since we don't know, return Invalid data for now.
            Err("Invalid data".to_string())
        },
        ParamType::FixedArray(_, _) => Err("Invalid data".to_string()),
        ParamType::Tuple(_) => Err("Invalid data".to_string()),
        ParamType::String => Err("Invalid data".to_string()),
    }
}
